from pathlib import Path
from html import escape
slides = [
('MARS SURVIVAL','Explore. Navigate. Survive.','An educational Marswalk planner connecting NASA observations, scientific destinations and mission constraints.','/textures/mars-globe.webp'),
('A science mission in Jezero','Investigate ancient environments','Select a verified Perseverance rover stop. Compare rover exploration locations with orbital terrain; inspect the linked NASA source.','/textures/jezero-ctx.webp'),
('NASA evidence in one map','Imagery · topography · thermal context','Viking global imagery and local MRO CTX imagery provide context. MOLA supplies regional elevation. TES is a rendered thermal-inertia overview, not local air temperature.','/textures/mola-elevation.webp'),
('Plan the Marswalk','Start → waypoint → science destination','Direct great-circle routes use Mars geometry. The planner calculates distance, interpolated elevation, regional ascent and estimated EVA duration.','/textures/jezero-ctx.webp'),
('Review the constraints','Resources and uncertainty stay visible','Configure crew, equipment load, oxygen, battery and reserves. Calculated warnings flag exceeded limits. The 0.25° MOLA grid cannot resolve local rocks or establish walkability.',None),
('Explore a 120-sol scenario','A deterministic resource model','Three illustrative kits model oxygen, water, food, solar power and batteries. Change equipment, add a hypothetical dust storm and scrub the computed timeline.',None),
('Evidence before confidence','Try the mission-planning prototype','Educational use only; no operational navigation or astronaut safety certification. NASA/JPL/GSFC/USGS/ASU and instrument teams credited in Data Sources. OpenAI Codex assisted with code, tests and documentation.',None),
]
body=''.join(f'<section class="slide" {"" if i==0 else "hidden"}><div><small>MARS SURVIVAL / {i+1:02d}</small><h1>{escape(title)}</h1><h2>{escape(sub)}</h2><p>{escape(text)}</p><a href="/" target="_blank">Open the application ↗</a></div>'+ (f'<img src="{asset}" alt="NASA Mars data visualization; provenance in the application"/>' if asset else '<div class="graphic">'+['','', '', '', 'EVA<br>O₂ · ENERGY · TIME','120<br>SOLS','EXPLORE<br>NAVIGATE<br>SURVIVE'][i]+'</div>')+'</section>' for i,(title,sub,text,asset) in enumerate(slides))
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>MARS SURVIVAL — Seven-slide demo</title><style>*{box-sizing:border-box}body{margin:0;background:#0b1016;color:#eee7df;font-family:system-ui,sans-serif}.slide{min-height:90vh;padding:8vw;display:grid;grid-template-columns:1.2fr 1fr;gap:5vw;align-items:center}.slide[hidden]{display:none}small{letter-spacing:3px;color:#e5a27c}h1{font-size:clamp(32px,5vw,72px);line-height:1.05;margin:25px 0}h2{font-size:clamp(18px,2vw,26px);font-weight:400;color:#dcb397}p{font-size:clamp(16px,1.7vw,23px);line-height:1.6;color:#b6bfc5}a{color:#a0d2ce}img{width:100%;border-radius:8px;border:1px solid #38414a}.graphic{font-size:clamp(30px,5vw,74px);color:#d49c78;border-left:1px solid #6b4c37;padding:40px}nav{position:fixed;bottom:0;left:0;right:0;background:#111921;padding:15px 30px;display:flex;gap:20px;align-items:center}button{background:#dca17d;color:#171717;border:0;padding:10px 18px;border-radius:4px;cursor:pointer}button:disabled{opacity:.4}button:focus-visible,a:focus-visible{outline:3px solid #9bd6d1;outline-offset:4px}#count{margin-left:auto}@media(max-width:700px){.slide{grid-template-columns:1fr;padding:35px 25px 100px}img{max-height:230px;object-fit:cover}.graphic{font-size:34px;padding:15px}}@media print{.slide,.slide[hidden]{display:grid;min-height:100vh;break-after:page}nav{display:none}}</style>'''+body+'''<nav aria-label="Slide controls"><button id="prev">Previous</button><button id="next">Next</button><button id="play">Play 30 seconds</button><span id="count" aria-live="polite"></span></nav><script>const slides=[...document.querySelectorAll('.slide')];let n=0,timer;function show(i){n=Math.max(0,Math.min(6,i));slides.forEach((s,j)=>s.hidden=j!==n);document.querySelector('#count').textContent=`${n+1} / 7`;document.querySelector('#prev').disabled=n===0;document.querySelector('#next').disabled=n===6}function stop(){clearInterval(timer);timer=null;document.querySelector('#play').textContent='Play 30 seconds'}document.querySelector('#prev').onclick=()=>{stop();show(n-1)};document.querySelector('#next').onclick=()=>{stop();show(n+1)};document.querySelector('#play').onclick=()=>{if(timer){stop();return}show(0);document.querySelector('#play').textContent='Pause';timer=setInterval(()=>{if(n===6){stop();return}show(n+1)},30000/7)};document.onkeydown=e=>{if(e.key==='ArrowRight'){stop();show(n+1)}if(e.key==='ArrowLeft'){stop();show(n-1)}};show(0);</script></html>'''
Path('public/demo.html').write_text(html)
